// Package testpki writes, for tests, the directories a sub CA of another PKI issues: laid out as
// a bundle, its certificates naming a CRL, which a bundle generated by rat-tool never does.
package testpki

import (
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/rand"
	"crypto/x509"
	"crypto/x509/pkix"
	"encoding/pem"
	"math/big"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/hekmon/rat/mtls"
)

// NewSubCA writes the directories of tenant as a sub CA of another PKI issues them, laid out as
// a bundle: the server, and clients alice and bob, their certificates naming crlURL as their CRL
// distribution point, and carol, whose certificate names none, refusing such a server.
func NewSubCA(t testing.TB, tenant, crlURL string) *PKI {
	t.Helper()
	now := time.Now()
	caKey, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	caTemplate := &x509.Certificate{SerialNumber: big.NewInt(1), Subject: pkix.Name{CommonName: tenant},
		NotBefore: now.Add(-time.Hour), NotAfter: now.Add(time.Hour), IsCA: true, BasicConstraintsValid: true,
		KeyUsage: x509.KeyUsageCertSign | x509.KeyUsageCRLSign, MaxPathLenZero: true}
	caDER, err := x509.CreateCertificate(rand.Reader, caTemplate, caTemplate, &caKey.PublicKey, caKey)
	if err != nil {
		t.Fatal(err)
	}
	ca, err := x509.ParseCertificate(caDER)
	if err != nil {
		t.Fatal(err)
	}
	pki := &PKI{Dir: filepath.Join(t.TempDir(), "bundle"), t: t, ca: ca, caDER: caDER, key: caKey,
		serials: map[string]*big.Int{}, sides: map[string]*side{}}
	for _, s := range []*side{
		{name: "server", common: tenant, dir: mtls.ServerDir(pki.Dir), role: "server", usage: x509.ExtKeyUsageServerAuth,
			crl: crlURL},
		{name: "alice", common: "alice", dir: mtls.ClientDir(pki.Dir, "alice"), role: "client",
			usage: x509.ExtKeyUsageClientAuth, crl: crlURL},
		{name: "bob", common: "bob", dir: mtls.ClientDir(pki.Dir, "bob"), role: "client",
			usage: x509.ExtKeyUsageClientAuth, crl: crlURL},
		{name: "carol", common: "carol", dir: mtls.ClientDir(pki.Dir, "carol"), role: "client",
			usage: x509.ExtKeyUsageClientAuth},
	} {
		pki.sides[s.name] = s
		pki.issue(s, true, time.Time{})
	}
	return pki
}

// side is a directory the CA issued, and what its certificate carries.
type side struct {
	name, common, dir, role string
	usage                   x509.ExtKeyUsage
	// crl is the distribution point its certificate names, none if empty
	crl string
	key *ecdsa.PrivateKey
}

// Renew issues the side name ("server" for the server) a new certificate, with a new key if
// asked, and writes it in place of the one it holds, as a renewal does: written next to the old
// files, then renamed in place. It returns the serial number of the new certificate.
func (p *PKI) Renew(name string, newKey bool) *big.Int {
	p.t.Helper()
	s, ok := p.sides[name]
	if !ok {
		p.t.Fatalf("no side %q", name)
	}
	return p.issue(s, newKey, time.Time{})
}

// Expiring issues the side name ("server" for the server) a new certificate, of the same key,
// expiring at notAfter, and writes it in place of the one it holds (see Renew). It returns the
// serial number of the new certificate. X.509 encodes notAfter to the second, truncated: an
// expiry a second from now may come at once, so a test needing time before it passes a whole
// second.
func (p *PKI) Expiring(name string, notAfter time.Time) *big.Int {
	p.t.Helper()
	s, ok := p.sides[name]
	if !ok {
		p.t.Fatalf("no side %q", name)
	}
	return p.issue(s, false, notAfter)
}

// issue writes the files of s with a new certificate, and a new key if asked, expiring at
// notAfter, or in an hour if zero, returning the serial of the certificate.
func (p *PKI) issue(s *side, newKey bool, notAfter time.Time) *big.Int {
	p.t.Helper()
	if newKey || s.key == nil {
		key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
		if err != nil {
			p.t.Fatal(err)
		}
		s.key = key
	}
	p.issued++
	now := time.Now()
	if notAfter.IsZero() {
		notAfter = now.Add(time.Hour)
	}
	template := &x509.Certificate{SerialNumber: big.NewInt(int64(p.issued + 1)), Subject: pkix.Name{CommonName: s.common},
		NotBefore: now.Add(-time.Hour), NotAfter: notAfter, KeyUsage: x509.KeyUsageDigitalSignature,
		ExtKeyUsage: []x509.ExtKeyUsage{s.usage}}
	if s.crl != "" {
		template.CRLDistributionPoints = []string{s.crl}
	}
	certDER, err := x509.CreateCertificate(rand.Reader, template, p.ca, &s.key.PublicKey, p.key)
	if err != nil {
		p.t.Fatal(err)
	}
	keyDER, err := x509.MarshalPKCS8PrivateKey(s.key)
	if err != nil {
		p.t.Fatal(err)
	}
	if err = os.MkdirAll(s.dir, 0o700); err != nil {
		p.t.Fatal(err)
	}
	for file, block := range map[string]*pem.Block{
		"ca.crt":        {Type: "CERTIFICATE", Bytes: p.caDER},
		s.role + ".crt": {Type: "CERTIFICATE", Bytes: certDER},
		s.role + ".key": {Type: "PRIVATE KEY", Bytes: keyDER},
	} {
		path := filepath.Join(s.dir, file)
		if err = os.WriteFile(path+".new", pem.EncodeToMemory(block), 0o600); err != nil {
			p.t.Fatal(err)
		}
		if err = os.Rename(path+".new", path); err != nil {
			p.t.Fatal(err)
		}
	}
	p.serials[s.name] = template.SerialNumber
	return template.SerialNumber
}

// PKI is a sub CA of another PKI, and the directories it issued (see NewSubCA).
type PKI struct {
	// Dir holds the directories, laid out as a bundle.
	Dir   string
	t     testing.TB
	ca    *x509.Certificate
	caDER []byte
	key   *ecdsa.PrivateKey
	// serials are the serial numbers of the certificate each side holds, sides what it carries;
	// issued counts the certificates issued, for their serials
	serials map[string]*big.Int
	sides   map[string]*side
	issued  int
}

// CRL returns a CRL of the CA in DER, valid from an hour ago for two hours, or stale if asked,
// revoking the certificates of the names given ("server" for the server).
func (p *PKI) CRL(stale bool, revoked ...string) []byte {
	thisUpdate := time.Now().Add(-time.Hour)
	if stale {
		thisUpdate = time.Now().Add(-3 * time.Hour)
	}
	return p.CRLAt(thisUpdate, thisUpdate.Add(2*time.Hour), revoked...)
}

// CRLAt returns a CRL of the CA in DER, issued at thisUpdate, stale at nextUpdate, revoking the
// certificates of the names given ("server" for the server).
func (p *PKI) CRLAt(thisUpdate, nextUpdate time.Time, revoked ...string) []byte {
	p.t.Helper()
	var entries []x509.RevocationListEntry
	for _, name := range revoked {
		entries = append(entries, x509.RevocationListEntry{SerialNumber: p.serials[name], RevocationTime: thisUpdate})
	}
	der, err := x509.CreateRevocationList(rand.Reader, &x509.RevocationList{Number: big.NewInt(1),
		ThisUpdate: thisUpdate, NextUpdate: nextUpdate, RevokedCertificateEntries: entries}, p.ca, p.key)
	if err != nil {
		p.t.Fatal(err)
	}
	return der
}

// SubCABundle is NewSubCA, returning its directory and its CRL function.
func SubCABundle(t testing.TB, tenant, crlURL string) (string, func(stale bool, revoked ...string) []byte) {
	t.Helper()
	pki := NewSubCA(t, tenant, crlURL)
	return pki.Dir, pki.CRL
}
